      const li = el("li"); const b = el("button", "addhit"); b.type = "button";
      const years = e.s.map((sv) => sv[1]), span = Math.min(...years) === Math.max(...years) ? String(years[0]) : `${Math.min(...years)}–${Math.max(...years)}`;
