      const b = el("button", "segbtn small", l); b.type = "button"; b.setAttribute("aria-pressed", String(state.cmp.type === t));
      b.addEventListener("click", () => { if (state.cmp.type !== t) { state.cmp.type = t; savePrefs(); render(); } });
