      const o = {}; (p.type === "H" ? J.hk : J.pk).forEach((k, i) => { o[k] = a[i] || 0; }); fDerive(o, p.type === "H" ? "H" : "P");
      const grp = p.type === "H" ? "H" : "P", role = p.type === "P" ? (o.GS * 2 >= (o.G || 1) ? "SP" : "RP") : null;
